PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl2bench: <http://benchmark/OWL2Bench#>
PREFIX agent: <https://example.org/agent-loop#>
SELECT ?person ?room ?seconds WHERE {
  ?person a owl2bench:T20CricketFan ;
          agent:mailbox ?room .
  ?room agent:travelSeconds ?seconds .
}
ORDER BY ?seconds ?person

closure_index.text:
index = cls()
for subject, predicate, value in triples:
    if predicate == RDF.type:
        if value == STUDENT:
            index.students.add(subject)
        elif value == T20_CRICKET_FAN:
            index.fans.add(subject)
    elif predicate == IS_MEMBER_OF:
        index.members[value].add(subject)
    elif predicate == TAKES_COURSE:
        index.courses[subject].append(value)
